package com.portfolio.assetory.access.domain;
import java.time.LocalDateTime; import com.portfolio.assetory.member.domain.User; import com.portfolio.assetory.order.domain.OrderItem; import jakarta.persistence.*;
@Entity @Table(name="product_access") public class ProductAccess {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id",nullable=false)private User user;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="order_item_id",nullable=false,unique=true)private OrderItem orderItem;@Column(nullable=false)private String status;@Column(nullable=false)private LocalDateTime grantedAt;@Column(nullable=false)private int downloadCount;protected ProductAccess(){}public static ProductAccess grant(User user,OrderItem item){ProductAccess a=new ProductAccess();a.user=user;a.orderItem=item;a.status="ACTIVE";a.grantedAt=LocalDateTime.now();return a;}public void revoke(){status="REVOKED";}public OrderItem getOrderItem(){return orderItem;}public LocalDateTime getGrantedAt(){return grantedAt;}}
